namespace sv_655b22ed172e4da7aefc64f1018e7818.Services;

/// <summary>
/// Scoped service holding the currently selected warehouse for a single user circuit.
/// Components subscribe to OnChange to react when the warehouse selection changes.
/// </summary>
public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";
    public string SelectedWarehouseName => Warehouses.TryGetValue(SelectedWarehouseId, out var name) ? name : SelectedWarehouseId;

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["warehouse-a"] = "Warehouse A – East",
        ["warehouse-b"] = "Warehouse B – West",
        ["warehouse-c"] = "Warehouse C – Central"
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_655b22ed172e4da7aefc64f1018e7818.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the current warehouse.
/// Supports polling with start/stop and notifies all subscribers when data changes.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired when alert data changes. Subscribers must wrap StateHasChanged in InvokeAsync
    /// because this fires from a background timer thread.
    /// </summary>
    public event Action? OnChange;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants polling to be active. Polling runs while at least one subscriber exists.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling. Stops when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelPolling();
        }
    }

    /// <summary>
    /// Forces an immediate refresh of the alert data and notifies subscribers.
    /// </summary>
    public async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnChange?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Immediately fetch on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
                OnChange?.Invoke();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void OnWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            // Warehouse changed while polling is active — refresh immediately
            _ = RefreshAsync();
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        CancelPolling();
    }
}

