@rendermode InteractiveServer
@inject WarehouseState Warehouse
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select" class="form-label mb-0 me-2 text-white">Site:</label>
    <select id="warehouse-select" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@Warehouse.SelectedWarehouseId" @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            Warehouse.SetWarehouse(id);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        Warehouse.OnChange -= OnStateChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LowStockCount > 0)
{
    <span class="badge bg-danger ms-2">@AlertService.LowStockCount</span>
}
else
{
    <span class="badge bg-success ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnChange -= _handler;
    }
}

