@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @Warehouse.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">Currently viewing: <strong>@Warehouse.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.LowStockCount > 5 ? "border-danger" : "border-warning")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="display-6">@Warehouse.SelectedWarehouseName</p>
                <p class="text-muted">Change the warehouse using the top-bar dropdown</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Manual Refresh</h5>
                <button class="btn btn-outline-primary mt-2" @onclick="RefreshNow">
                    🔄 Refresh Now
                </button>
                <p class="text-muted mt-2">Fetch latest alert count immediately</p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnChange += _alertHandler;
        Warehouse.OnChange += _warehouseHandler;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    private async Task RefreshNow()
    {
        await AlertService.RefreshAsync();
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnChange -= _alertHandler;
        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;
    }
}

